local function Z(a,b) local x=E[S.char(98,105,116,51,50)] if x then return x[S.char(98,120,111,114)](a,b) end x=E[S.char(98,105,116)] if x and x[S.char(98,120,111,114)] then return x[S.char(98,120,111,114)](a,b) end local r,p=0,1 a,b=M.floor(a),M.floor(b) while a>0 or b>0 do local u,v=a%2,b%2 if u~=v then r=r+p end a,b,p=(a-u)/2,(b-v)/2,p*2 end return r end
